/**
 * Numbers behind the math chapters. Generated by `python -m electionlab.exhibits`
 * from verified market tapes and the frozen result tables. Do not edit by hand.
 */
import raw from './exhibits.json';

export type Scenario = 'normal' | 'stressed';

export type Interval = { mean: number; se_iid: number; boot_lo: number; boot_hi: number; boot_share_positive: number };
export type Bucket = { lo: number; hi: number; n: number; wins: number; mean_p: number; mean_ask: number; win_rate: number; lo95: number; hi95: number };
export type Cell = { fills: number; shares: number; cost: number; payout: number; markets: number; markets_won: number; net: number; avg_cost: number; win_rate: number };
export type DateRow = { date: string; scheduled: number; filled: number; shares: number; cost: number; net: number };
export type TypeRow = { type: string; scheduled: number; listed: number; positions: number; won: number; shares: number; cost: number; net: number };
export type Ranked = { key: string; side: string; shares: number; cost: number; net: number };

export type ScenarioExhibits = {
  identity: {
    shares: number; cost: number; fees: number; friction: number; redemption: number; principal: number; net: number;
    avg_price: number; avg_cost: number; win_rate: number; edge_per_share: number; margin: number; turnover: number; return_pct: number;
  };
  capital: {
    orders: number; fills: number; requested_shares: number; funded_shares: number; constrained_batches: number;
    rejected_requests: number; maximum_live_orders: number; minimum_free_cash: number; maximum_order_cash: number;
  };
  dates: DateRow[];
  positions: {
    positions: number; settled: number; won: number; by_type: TypeRow[];
    by_year: { year: string; positions: number; won: number; shares: number; cost: number; net: number }[];
    largest_losses: Ranked[]; largest_gains: Ranked[];
  };
  fills: {
    by_day: (Cell & { day: number })[];
    by_price: (Cell & { lo: number; hi: number })[];
    by_anchor: { below: Cell; at_or_above: Cell };
    by_phase: { before: Cell; after: Cell };
  };
  risk: {
    own_variance: number; same_night_cross: number; null_mean: number; net: number; sd_independent: number; z_independent: number;
    rho_positions: number; active_dates: number; winning_dates: number; losing_dates: number;
    date_mean: number; date_sd: number; date_t: number; boot_lo: number; boot_median: number; boot_hi: number;
    boot_share_positive: number; boot_draws: number; boot_hist: { start: number; width: number; counts: number[] };
    top_date: string; top_date_net: number; top_date_share: number; net_without_top_date: number; largest_position_sd: number;
  };
  equity: { series: [number, number, number][]; peak_deployed: number; peak_day: number };
};

export type Exhibits = {
  cutoff: string;
  tapes: { listed: number; verified: boolean };
  types: string[];
  opening: {
    listed: number; quoted: number; tied: number; sided: number; settled: number; voting_dates: number; largest_nights: number[];
    mean_mid: number; mean_ask: number; win_rate: number; wins: number;
    gap_mid: Interval; gap_ask: Interval; net_per_share: Interval;
    brier: number; brier_base_rate: number; slope: number; intercept: number; price_outcome_corr: number;
    /** Intraclass correlation of standardized surprises within a voting date, and its range under shuffled dates. */
    same_night_corr: number; same_night_null_lo: number; same_night_null_hi: number; same_night_null_share_above: number;
    big_nights: { date: string; n: number; wins: number; mean_p: number; gap_mid: number }[];
    buckets: Bucket[];
    by_year: { year: string; n: number; mean_p: number; win_rate: number }[];
    by_type: { type: string; n: number; mean_p: number; win_rate: number }[];
  };
  scenarios: Record<Scenario, ScenarioExhibits>;
  /** One record per scheduled opportunity: [date index, type, listed, side, shares, result, net]. */
  universe: { dates: string[]; fields: string[]; cells: number[][] };
  /** Days from the start of voting day (UTC) to settlement. */
  lockup: {
    contracts: number; median_days: number; p90_days: number; longest_days: number; cost_weighted_days: number;
    by_type: { type: string; median_days: number; longest_days: number }[];
  };
  accounts: { period: string; scenario: Scenario; net: number; return_pct: number; filled: number; elections: number }[];
  start_days: { days: number; scenario: Scenario; net: number; filled: number }[];
};

export const X = raw as unknown as Exhibits;
export const NORMAL = X.scenarios.normal;
export const STRESSED = X.scenarios.stressed;

/** Extra modeled cost per filled share, in dollars. */
export const FRICTION: Record<Scenario, number> = { normal: 0.001, stressed: 0.011 };
/** Unrounded taker fee per share at price p. */
export const fee = (p: number) => 0.07 * p * (1 - p);

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
/** "2024-11-05" to "5 Nov 2024". */
export function longDate(iso: string) {
  const [y, m, d] = iso.split('-').map(Number);
  return `${d} ${MONTHS[m! - 1]} ${y}`;
}
export function shortDate(iso: string) {
  const [y, m, d] = iso.split('-').map(Number);
  return `${d} ${MONTHS[m! - 1]} ${String(y).slice(2)}`;
}
